const fence3 = String.fromCharCode(96,96,96);
const raw = $('Repost: Analizar imagen').first().json.content.parts[0].text;
const clean = raw.replace(new RegExp(fence3 + 'json','gi'), '').replace(new RegExp(fence3,'g'), '').trim();
