const items = $input.all();
const data = $('Telegram Trigger').first().json.callback_query?.data || 'pub_1';
let targetRow = null, choice = 'op1';
if (String(data).startsWith('pubR_')) {
  const p = String(data).split('_');
  targetRow = Number(p[1]);
  choice = p[2] === 'final' ? 'final' : ('op' + p[2]);
} else if (data === 'pub_2') choice = 'op2';
else if (data === 'pub_3') choice = 'op3';
else if (data === 'pub_final') choice = 'final';
else choice = 'op1';
const rows = items.map(i => i.json);
let row;
if (targetRow != null) row = rows.find(r => Number(r.row_number) === targetRow) || rows[rows.length - 1];
else row = rows[rows.length - 1];
return [{ json: { ...row, _choice: choice } }];

const items = $input.all();
const data = $('Telegram Trigger').first().json.callback_query.data;
const target = Number(String(data).split('_')[1]);
const chatId = $('Telegram Trigger').first().json.callback_query.message.chat.id;
const rows = items.map(i => i.json).filter(j => j && j.row_number != null);
const row = rows.find(r => Number(r.row_number) === target) || rows[rows.length - 1] || {};
return [{ json: { rowNumber: row.row_number, op1: row.Copy_Op1 || '', op2: row.Copy_Op2 || '', op3: row.Copy_Op3 || '', imageURL: row.ImageURL || '', chatId } }];

const crypto = require('crypto');
const KEY = Buffer.from($env.POSTLY_ENC_KEY, 'hex');
function decrypt(val) {
  if (!val || typeof val !== 'string' || !val.startsWith('enc:')) return val; // texto plano (compat)
  const raw = Buffer.from(val.slice(4), 'base64');
  const iv  = raw.subarray(0, 12);
  const tag = raw.subarray(12, 28);
  const ct  = raw.subarray(28);
  const d = crypto.createDecipheriv('aes-256-gcm', KEY, iv);
  d.setAuthTag(tag);
  return Buffer.concat([d.update(ct), d.final()]).toString('utf8');
}
return $input.all().map(item => ({ json: { ...item.json, AccessToken: decrypt(item.json.AccessToken) } }));

