// HU8 — parsea la detección visual de Gemini (fail-open ante JSON inválido)
const raw = ($('HU8: Detección visual').first().json.content.parts[0].text) || '';
let parsed = { tiene_precio: false, detalle: '' };
try {
  parsed = JSON.parse(raw.replace(/```json/gi, '').replace(/```/g, '').trim());
} catch (e) { /* Gemini no devolvió JSON limpio -> no bloquear */ }
return [{ json: {
  tiene_precio: parsed.tiene_precio === true,
  detalle: parsed.detalle || '',
  secure_url: $('HTTP Request').first().json.secure_url
} }];

// HU5 — buffer en archivo local (fs.appendFileSync se serializa en el proceso Node -> sin clobbering)
const fsm = require('fs');
const BUF = '/tmp/postly_carrusel_buffer.tsv';
const msg = $('Telegram Trigger').first().json.message;
const gid = 'g_' + String(msg.media_group_id);
const photo = msg.photo.reduce((a, b) => (a.file_size > b.file_size ? a : b));
const line = [gid, photo.file_id, String(msg.chat.id), Date.now()].join('\t') + '\n';
fsm.appendFileSync(BUF, line, 'utf8');
return [{ json: { gid, file_id: photo.file_id, chatId: String(msg.chat.id) } }];

const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
  items[i].json.fotoBase64 = buffer.toString('base64');
}
return items;

// HU5 — junta las N secure_url en un solo item, conservando chatId/gid desde Recolectar
const urls = $input.all().map(it => it.json.secure_url);
const rec = $('HU5: ¿Ganador?').all();
const chatId = rec[0].json.chatId;
const gid = rec[0].json.gid;
const images = urls.map((u, i) => ({ idx: i, url: u }));
return [{ json: { chatId, gid, total: images.length, images, urlList: urls.join(',') } }];

// HU5 — ganador determinístico: lee el archivo, filtra mi gid, gana la 1ra línea; junta los N file_id y limpia
const fsm = require('fs');
const BUF = '/tmp/postly_carrusel_buffer.tsv';
const myFileId = String($('HU5: Buffer grupo').first().json.file_id);
const gid = String($('HU5: Buffer grupo').first().json.gid);
let lines = [];
try { lines = fsm.readFileSync(BUF, 'utf8').split('\n').filter(Boolean); } catch (e) {}
const mine = lines.map(l => l.split('\t')).filter(p => p[0] === gid);
if (!mine.length) return [];
if (String(mine[0][1]) !== myFileId) return []; // no soy el ganador -> corto
const seen = new Set(); const fileIds = [];
for (const p of mine) { const fid = p[1]; if (!seen.has(fid)) { seen.add(fid); fileIds.push(fid); } }
const ten = fileIds.slice(0, 10);
const chatId = mine[0][2];
const rest = lines.filter(l => l.split('\t')[0] !== gid); // limpiar las líneas de este grupo
try { fsm.writeFileSync(BUF, rest.length ? rest.join('\n') + '\n' : '', 'utf8'); } catch (e) {}
return ten.map((fid, i) => ({ json: { file_id: fid, idx: i, chatId, gid, total: ten.length } }));

// HU5 — confirm: elige set (ai u original) según el callback y lo recupera de static data
const cb = $('Telegram Trigger').first().json.callback_query;
const data = String(cb.data || '');
const useAi = data.startsWith('cfmCar_');
const gid = data.replace(/^cfmCar_/, '').replace(/^origCar_/, '');
const store = $getWorkflowStaticData('global');
const set = store['carousel_' + gid] || {};
const urls = (useAi ? set.aiUrls : set.origUrls) || [];
return [{ json: { chatId: set.chatId || cb.message.chat.id, gid, total: urls.length, urls, urlList: urls.join(','), useAi } }];

// HU5 — parsea los 3 copys, persiste set+copys para 2b, arma textos de display con encabezado
const fence3 = String.fromCharCode(96,96,96);
const raw = ($('HU5: Generar copys').first().json.content.parts[0].text) || '';
const clean = raw.replace(new RegExp(fence3 + 'json','gi'), '').replace(new RegExp(fence3,'g'), '').trim();
let o = { opcion1: '', opcion2: '', opcion3: '' };
try { o = JSON.parse(clean); } catch (e) {}
const prep = $('HU5: Preparar set').first().json;
const store = $getWorkflowStaticData('global');
const prev = store['carousel_' + prep.gid] || {};
store['carousel_' + prep.gid] = { ...prev, urls: prep.urls, total: prep.total, chatId: prep.chatId, copys: [o.opcion1, o.opcion2, o.opcion3] };
return [{ json: { chatId: prep.chatId, gid: prep.gid, cover: (prep.urls && prep.urls[0]) || '', c1: o.opcion1 || '', c2: o.opcion2 || '', c3: o.opcion3 || '',
  op1: '📝 *Opción Informativa*\n\n' + (o.opcion1 || ''),
  op2: '💎 *Opción Vendedora*\n\n' + (o.opcion2 || ''),
  op3: '🎉 *Opción Divertida*\n\n' + (o.opcion3 || '') } }];

// HU5 — marca edición de carrusel pendiente para este chat (editCar_<gid>_<n>)
const cb = $('Telegram Trigger').first().json.callback_query;
const data = String(cb.data || '');
const rest = data.slice('editCar_'.length);
const lastU = rest.lastIndexOf('_');
const gid = rest.slice(0, lastU);
const n = rest.slice(lastU + 1);
const chatId = String(cb.message.chat.id);
const store = $getWorkflowStaticData('global');
store['editPending_' + chatId] = { gid, n: Number(n), ts: Date.now() };
return [{ json: { chatId, gid, n } }];

// HU5 — ¿hay una edición de carrusel pendiente para este chat? (intercepta texto plano)
const msg = $('Telegram Trigger').first().json.message;
const chatId = String(msg.chat.id);
const text = (msg && msg.text) || '';
const store = $getWorkflowStaticData('global');
const pend = store['editPending_' + chatId];
const pending = !!(pend && text);
return [{ json: { pending, chatId, text, gid: pend ? pend.gid : '', n: pend ? pend.n : 0 } }];

// HU5 — aplica el texto editado al caption del carrusel y limpia el flag
const inp = $json;
const store = $getWorkflowStaticData('global');
const set = store['carousel_' + inp.gid] || {};
const copys = set.copys || ['', '', ''];
copys[inp.n - 1] = inp.text;
set.copys = copys;
store['carousel_' + inp.gid] = set;
delete store['editPending_' + inp.chatId];
return [{ json: { chatId: inp.chatId, gid: inp.gid, n: inp.n, caption: inp.text } }];

// HU5 — analiza compliance+orden en una sola pasada de Gemini
const raw = ($('HU5: Analizar carrusel').first().json.content.parts[0].text) || '';
let p = { tiene_precio: false, detalle: '', orden: [], preview: '' };
try { p = JSON.parse(raw.replace(/```json/gi, '').replace(/```/g, '').trim()); } catch (e) {}
const juntar = $('HU5: Juntar URLs').first().json;
const images = juntar.images;
if (p.tiene_precio === true) {
  return [{ json: { tiene_precio: true, detalle: p.detalle || '', chatId: juntar.chatId, gid: juntar.gid } }];
}
let orden = Array.isArray(p.orden) ? p.orden.map(Number).filter(n => Number.isInteger(n) && n >= 1 && n <= images.length).map(n => n - 1) : [];
const seen = new Set(orden);
for (let i = 0; i < images.length; i++) if (!seen.has(i)) { orden.push(i); seen.add(i); }
orden = orden.slice(0, images.length);
const orderedUrls = orden.map(i => images[i].url);
const lineas = orden.map((o, pos) => `${pos + 1}. imagen #${o + 1}`).join('\n');
const mensaje = `🖼️ Recibí tu carrusel de ${images.length} imágenes.\n\n*Orden narrativo propuesto:*\n${lineas}\n\n_${p.preview || 'Secuencia optimizada para retención.'}_\n\n¿Lo usamos así o preferís tu orden original?`;
const store = $getWorkflowStaticData('global');
store['carousel_' + juntar.gid] = { aiUrls: orderedUrls, origUrls: images.map(im => im.url), total: images.length, chatId: juntar.chatId };
return [{ json: { tiene_precio: false, chatId: juntar.chatId, gid: juntar.gid, total: images.length, mensaje } }];

const crypto = require('crypto');
const KEY = Buffer.from($env.POSTLY_ENC_KEY, 'hex');
function decrypt(val) {
  if (!val || typeof val !== 'string' || !val.startsWith('enc:')) return val;
  const raw = Buffer.from(val.slice(4), 'base64');
  const iv = raw.subarray(0, 12), tag = raw.subarray(12, 28), ct = raw.subarray(28);
  const d = crypto.createDecipheriv('aes-256-gcm', KEY, iv); d.setAuthTag(tag);
  return Buffer.concat([d.update(ct), d.final()]).toString('utf8');
}
return $input.all().map(item => ({ json: { ...item.json, AccessToken: decrypt(item.json.AccessToken) } }));

// HU5 2b — arma el caption final (HU7 precios + HU9 firma) y recupera urls del set
const cb = $('Telegram Trigger').first().json.callback_query;
const data = String(cb.data || '');
const rest = data.slice('pubCar_'.length);
const lastU = rest.lastIndexOf('_');
const gid = rest.slice(0, lastU);
const n = Number(rest.slice(lastU + 1));
const chatId = String(cb.message.chat.id);
const store = $getWorkflowStaticData('global');
const set = store['carousel_' + gid] || {};
const urls = set.urls || [];
let caption = (set.copys && set.copys[n - 1]) || '';
// HU7 — precios en texto
const patrones = [
  /(\$|u\$s|us\$|ar\$|€|£)\s*\d/i,
  /\d\s*[.,]?\d*\s*(pesos?|ars|usd|u\$d|d[oó]lares?|euros?|mangos?|lucas?)\b/i,
  /\d+[.,]\d{3}/,
  /\d+\s*%\s*(off|desc|descuento)/i,
  /\b(ofertas?|promos?|promoci[oó]n(?:es)?|descuentos?|rebajas?|barat[oa]s?|econ[oó]mic[oa]s?|gratis|2x1|3x2|cuotas?|financiaci[oó]n(?:es)?|sin\s+inter[eé]s)\b/i,
  /\b(precios?|cuesta|vale|abon[aá]s?)\s*(?:es|son|de|desde|:)?\s*\$?\s*\d/i
];
let precio = null;
for (const p of patrones) { const m = caption.match(p); if (m) { precio = m[0]; break; } }
if (precio) return [{ json: { blocked: true, chatId, blockMsg: '⚠️ El texto tiene contenido prohibido: "' + precio + '". Editá la opción e intentá de nuevo.' } }];
// HU9 — firma desde Config
const cfg = {};
try { const row = $('HU5: Pub leer Config').first().json || {}; for (const h of Object.keys(row)) cfg[h.trim().toLowerCase()] = String(row[h] ?? '').trim(); } catch (e) {}
const firmaLinea = cfg.firma || '-- Consultora de Belleza Independiente Mary Kay --';
const contacto = cfg.contacto || '';
caption = caption.trim();
caption = caption.split(firmaLinea).join('').trim();
if (contacto) caption = caption.split(contacto).join('').trim();
caption = caption + '\n' + firmaLinea;
if (contacto) caption = caption + '\n' + contacto;
return [{ json: { blocked: false, chatId, gid, n, caption, copys: set.copys || [], urls, cover: urls[0] || '', total: urls.length } }];

