// Repost: HU8 parsear — parsea la detección visual de Gemini (fail-open ante JSON inválido)
const raw = ($('Repost: HU8 visual').first().json.content.parts[0].text) || '';
let parsed = { tiene_precio: false, detalle: '' };
try {
  parsed = JSON.parse(raw.replace(/```json/gi, '').replace(/```/g, '').trim());
} catch (e) { /* Gemini no devolvió JSON limpio -> no bloquear */ }
return [{ json: {
  tiene_precio: parsed.tiene_precio === true,
  detalle: parsed.detalle || '',
  secure_url: $('Repost: Elegir fila').first().json.ImageURL
} }];
